using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools are discovered via [McpServerToolType] on the class
/// and [McpServerTool] on each method. The SDK uses DI to resolve
/// constructor parameters automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the SDK resolves this from the DI container.
    // Register a named/typed HttpClient in Program.cs and it gets injected here.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _httpClient.GetFromJsonAsync<WttrResponse>(url, cancellationToken);

        if (response?.CurrentCondition is not [var current, ..])
            return $"Could not retrieve weather for '{city}'.";

        return $"""
            Weather for {city}:
              Temperature: {current.TempC}°C ({current.TempF}°F)
              Condition:   {current.WeatherDesc?.FirstOrDefault()?.Value ?? "Unknown"}
              Humidity:    {current.Humidity}%
              Wind:        {current.WindspeedKmph} km/h {current.WindDir}
            """;
    }

    [McpServerTool, Description("Get a short weather forecast (next 3 days).")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1";

        var response = await _httpClient.GetFromJsonAsync<WttrResponse>(url, cancellationToken);

        if (response?.Weather is not { Count: > 0 } days)
            return $"Could not retrieve forecast for '{city}'.";

        var lines = days.Select(d =>
            $"  {d.Date}: {d.MaxTempC}°C / {d.MinTempC}°C");

        return $"3-day forecast for {city}:\n{string.Join('\n', lines)}";
    }
}

// Minimal DTOs for the wttr.in JSON API
public record WttrResponse
{
    [JsonPropertyName("current_condition")]
    public List<CurrentCondition>? CurrentCondition { get; init; }

    [JsonPropertyName("weather")]
    public List<WeatherDay>? Weather { get; init; }
}

public record CurrentCondition
{
    [JsonPropertyName("temp_C")] public string? TempC { get; init; }
    [JsonPropertyName("temp_F")] public string? TempF { get; init; }
    [JsonPropertyName("humidity")] public string? Humidity { get; init; }
    [JsonPropertyName("windspeedKmph")] public string? WindspeedKmph { get; init; }
    [JsonPropertyName("winddir16Point")] public string? WindDir { get; init; }
    [JsonPropertyName("weatherDesc")] public List<WeatherDesc>? WeatherDesc { get; init; }
}

public record WeatherDesc
{
    [JsonPropertyName("value")] public string? Value { get; init; }
}

public record WeatherDay
{
    [JsonPropertyName("date")] public string? Date { get; init; }
    [JsonPropertyName("maxtempC")] public string? MaxTempC { get; init; }
    [JsonPropertyName("mintempC")] public string? MinTempC { get; init; }
}

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

// Register a typed HttpClient for WeatherTools.
// The DI container creates an HttpClient instance and injects it
// into the WeatherTools constructor automatically.
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.UserAgent.ParseAdd("McpServer/1.0");
});

// Register the MCP server with stdio transport.
// WithTools<T>() scans the type for [McpServerTool] methods and
// registers them for discovery and invocation.
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithTools<WeatherTools>();

await builder.Build().RunAsync();

